Item.method_code:
const { getItemTypeId } = ArasModules.metadata.itemType;

const getUserStartPage = () => {
	const { startingPage } = aras.user.userInfo;
	if (!startingPage) {
		return null;
	}

	const startPages = {
		Discussion: '../Modules/aras.innovator.SSVC/Views/MyDiscussions.html',
		'Activity Assignment' : 'InBasket/InBasket.html'
	};
	if (startPages[startingPage]) {
		const toc = window.mainLayout.navigationPanel.nav;
		const tocItem = [...toc.data.values()].find((tocItem) => tocItem.startPage === startPages[startingPage]);
		if (!tocItem) {
			return null;
		}

		return { ...tocItem };
	}

	const itemTypeId = getItemTypeId(startingPage);
	if (!itemTypeId) {
		return null;
	}

	return {
		itemTypeId
	};
};

const getStartItem = () => {
	const searchParams = new URLSearchParams(window.location.search);
	const startItemStr = searchParams.get('StartItem');
	const [type, itemId, version = 'exact'] = startItemStr?.split(':') || [];
	if (!type) {
		return null;
	}

	const itemTypeName = type === 'inbasket' ? 'InBasket Task' : type;
	const itemTypeId = getItemTypeId(itemTypeName);
	if (!itemTypeId) {
		return null;
	}

	const resultItem = {
		itemTypeId
	};

	if (!itemId) {
		return resultItem;
	}

	return {
		...resultItem,
		itemId,
		version
	};
};

const loginViewTabsJson = aras.getPreferenceItemProperty(
	'Core_GlobalLayout',
	null,
	'login_view_tabs'
);
const parsedTabsData = JSON.parse(loginViewTabsJson || '{}');
const { dockTabs = [], mainTabs = [], tabs = {}, selectedTabs = [] } = parsedTabsData;
const result = { dockTabs, mainTabs, tabs, selectedTabs };
const savedTabsExist = result.dockTabs.length > 0 || result.mainTabs.length > 0;
const userStartPage = savedTabsExist ? null : getUserStartPage();
if (userStartPage) {
	const userStartPageTabId = 'userStartPageTabId';

	result.mainTabs.push(userStartPageTabId);
	result.tabs[userStartPageTabId] = userStartPage;
}

const startItem = getStartItem();
if (startItem) {
	const startItemTabId = 'startItemTabId';

	result.mainTabs.push(startItemTabId);
	result.tabs[startItemTabId] = startItem;
	result.selectedTabs.push(startItemTabId);
}

return result;
